    "title": "晚上好，我是编辑陈醋。最近看综艺《我家那闺女》，跳水运动员张家齐和肖英杰的母女关系频频让我窒息。\\n\\n关于东亚家庭教育里习惯性的“否定”和“打压”，我不想赘述节目里那些我们都能共鸣的痛苦。\\n\\n想分享一个让我落泪的瞬间：\\n\\n和妈妈交谈的饭桌上，张家齐坦言，她已经接受了妈妈不会给她，也给不了她想要的安全感，“那我就自己给自己，我现在很强大。”\\n\\n这个瞬间带来的冲击是剧烈的。有微妙、确切的痛楚，还有紧随其后的钦佩。接受无法从父母身上获得自己想要的爱，是一种强大，而在这之后确信自己能大方地给予自己，",
